function mean(xs) {
  return xs.reduce((sum, x) => sum + x, 0) / xs.length;
}

function variance(xs) {
  const m = mean(xs);
  return xs.reduce((sum, x) => sum + (x - m) ** 2, 0) / (xs.length - 1);
}

function stdDev(xs) {
  return Math.sqrt(variance(xs));
}

